/**
 * Load and normalize a craft's command catalog.
 *
 * Every craft ships `commands`; some print JSON, some a fixed-width table.
 * Plugins use the catalog to tell the model which verbs exist, and the
 * snapshot files generated by `scripts/gen-catalogs.mjs` let a plugin answer
 * from disk when the binary is not installed yet.
 * @module @dsh-artcraft/craft-kit/catalog
 */

import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { CATALOG_CAPTURE_BYTES, runCraft } from './exec.js'
                                                                         

/** Directory holding this module's compiled/`src` file. */
const here = dirname(fileURLToPath(import.meta.url))

/** Where `scripts/gen-catalogs.mjs` writes snapshots, relative to a plugin package. */
export const CATALOG_DIR = 'catalog'

/** Infer the command family from its dotted id: `insert.chart` → `insert`. */
export function groupOf(id        )         {
  const dot = id.indexOf('.')
  return dot === -1 ? '(root)' : id.slice(0, dot)
}

/**
 * Normalize one raw catalog entry from any craft's JSON.
 *
 * Most crafts use `{ id, label, params, menu, shortcut }`; PdfCraft's `tools`
 * output instead uses `{ command, description, input_schema }`, so both shapes
 * are folded into the same record.
 */
function normalize(raw                         )                           {
  // `name` wins over `command`: PdfCraft's tool list carries the runnable tool
  // name in `name` and a UI-level command id in `command`, and only `name` works
  // with `pdfcraft-cli run`.
  const id = typeof raw.id === 'string' && raw.id.length > 0
    ? raw.id
    : typeof raw.name === 'string' && raw.name.length > 0
      ? raw.name
      : typeof raw.command === 'string' && raw.command.length > 0 ? raw.command : undefined
  if (id === undefined) return undefined
  const menu = Array.isArray(raw.menu) ? raw.menu.filter((m)              => typeof m === 'string') : undefined
  // PdfCraft describes parameters as a JSON Schema; render it back to a grammar
  // string so every craft's catalog reads the same way in the tool output.
  const schema = typeof raw.input_schema === 'object' && raw.input_schema !== null
    ? raw.input_schema                                                                                                 
    : undefined
  const params = typeof raw.params === 'string'
    ? raw.params
    : schema?.properties !== undefined
      ? Object.entries(schema.properties)
        .map(([key, node]) => `${key}${schema.required?.includes(key) === true ? '' : '?'}: ${node.type ?? 'value'}${node.description !== undefined ? ` (${node.description})` : ''}`)
        .join(', ')
      : undefined
  return {
    id,
    ...typeof raw.label === 'string' ? { label: raw.label } : {},
    ...params !== undefined && params.length > 0 ? { params } : {},
    ...menu !== undefined ? { menu } : {},
    ...typeof raw.shortcut === 'string' || raw.shortcut === null ? { shortcut: raw.shortcut                  } : {},
    ...Array.isArray(raw.aliases) ? { aliases: raw.aliases.filter((a)              => typeof a === 'string') } : {},
    ...typeof raw.interactive === 'boolean' ? { interactive: raw.interactive } : {},
    ...typeof raw.enabled === 'boolean' ? { enabled: raw.enabled } : {},
    ...typeof raw.description === 'string' ? { description: raw.description } : {},
    group: groupOf(id),
  }
}

/**
 * Parse a craft's `commands` output.
 * @param stdout - raw stdout of the `commands` subcommand.
 * @param json - whether the CLI was asked for JSON.
 * @returns every command the output described.
 */
export function parseCatalog(stdout        , json         )                 {
  const text = stdout.trim()
  if (text.length === 0) return []
  if (json || text.startsWith('[')) {
    try {
      const parsed          = JSON.parse(text)
      if (Array.isArray(parsed)) {
        return parsed
          .filter((entry)                                   => typeof entry === 'object' && entry !== null)
          .map(normalize)
          .filter((entry)                        => entry !== undefined)
      }
    } catch {
      // Fall through to the table parser: a CLI may ignore an unknown --json.
    }
  }
  return parseTable(text)
}

/**
 * Parse a craft's fixed-column `commands` table.
 *
 * Every table puts the id in the first column and keeps later columns
 * aligned, so a split on 2+ spaces is reliable; parameter grammars and long
 * labels wrap onto continuation lines that stay indented, and those are folded
 * back into the entry they belong to.
 * @param text - raw table output.
 * @returns every command the table described.
 */
export function parseTable(text        )                 {
  const out                 = []
  let current                                               
  const flush = ()       => {
    if (current === undefined) return
    const { id, columns } = current
    const rest = columns.join(' ').trim()
    const paramsMatch = /\bparams:\s*(\{.*)$/.exec(rest)
    const labelPart = paramsMatch === null ? rest : rest.slice(0, paramsMatch.index).trim()
    // Trailing `label  [Shortcut]` and an interleaved menu column.
    const shortcutMatch = /\[([^\]]+)\]\s*$/.exec(labelPart)
    const label = (shortcutMatch === null ? labelPart : labelPart.slice(0, shortcutMatch.index)).trim()
    out.push({
      id,
      ...label.length > 0 ? { label } : {},
      ...paramsMatch !== null ? { params: paramsMatch[1].replace(/\s+/g, ' ').trim() } : {},
      ...shortcutMatch !== null ? { shortcut: shortcutMatch[1] } : {},
      group: groupOf(id),
    })
    current = undefined
  }
  for (const raw of text.split('\n')) {
    if (raw.trim().length === 0) continue
    if (/^\s/.test(raw)) {
      // Continuation: a wrapped label/params line belongs to the open entry,
      // unless it begins a fresh block (params: on its own column).
      if (current !== undefined) current.columns.push(raw.trim())
      continue
    }
    flush()
    const columns = raw.trimEnd().split(/\s{2,}/).map(part => part.trim()).filter(part => part.length > 0)
    const id = columns[0] ?? ''
    if (id.length === 0 || /\s/.test(id) || !/^[\w.-]+$/.test(id)) continue
    current = { id, columns: columns.slice(1) }
  }
  flush()
  return out
}

/** Read a bundled catalog snapshot shipped beside a plugin package. */
export function readSnapshot(packageRoot        , craftId        )                             {
  try {
    const raw = readFileSync(join(packageRoot, CATALOG_DIR, `${craftId}.json`), 'utf8')
    const parsed          = JSON.parse(raw)
    if (!Array.isArray(parsed)) return undefined
    return parsed
      .filter((entry)                                   => typeof entry === 'object' && entry !== null)
      .map(normalize)
      .filter((entry)                        => entry !== undefined)
  } catch {
    return undefined
  }
}

