/**
 * Load a craft's catalog, preferring the installed binary.
 * @param profile - the craft profile.
 * @param binary - resolved binary, or `undefined` to use the snapshot.
 * @param packageRoot - plugin package root holding `catalog/`.
 * @param timeoutMs - budget for the live read.
 * @returns catalog commands plus where they came from.
 */
export async function loadCatalog(
  profile              ,
  binary                         ,
  packageRoot        ,
  timeoutMs = 30_000,
)                         {
  if (binary !== undefined) {
    const argv = [...profile.catalogArgs ?? ['commands', ...profile.catalogJson ? ['--json'] : []]]
    const result = await runCraft({
      profile, binary, argv, cwd: process.cwd(), timeoutMs, maxCaptureBytes: CATALOG_CAPTURE_BYTES,
    })
    const parsed = parseCatalog(result.stdout, profile.catalogJson)
    if (parsed.length > 0) return { commands: parsed, origin: 'live' }
    const detail = (result.stderr || result.stdout).trim().slice(0, 300)
    const snapshot = readSnapshot(packageRoot, profile.id)
    return snapshot !== undefined
      ? { commands: snapshot, origin: 'snapshot', note: `live catalog read failed: ${detail}` }
      : { commands: [], origin: 'empty', note: `live catalog read returned no commands: ${detail}` }
  }
  const snapshot = readSnapshot(packageRoot, profile.id)
  return snapshot !== undefined
    ? { commands: snapshot, origin: 'snapshot' }
    : { commands: [], origin: 'empty', note: `${profile.bin} is not installed and no catalog snapshot was bundled` }
}

/** All distinct command families in a catalog, in first-seen order. */
export function groupsOf(commands                         )           {
  const seen           = []
  for (const command of commands) {
    const group = command.group ?? groupOf(command.id)
    if (!seen.includes(group)) seen.push(group)
  }
  return seen
}

/**
 * Score a command against a free-text query, for search and ranking.
 * @param command - catalog entry.
 * @param needle - lowercased query.
 * @returns 0 when unrelated, higher when more relevant.
 */
export function score(command              , needle        )         {
  const id = command.id.toLowerCase()
  const label = (command.label ?? '').toLowerCase()
  const params = (command.params ?? '').toLowerCase()
  if (id === needle) return 100
  if (id.startsWith(needle)) return 60
  if (id.includes(needle)) return 40
  if (label.includes(needle)) return 25
  if (params.includes(needle)) return 5
  return 0
}
